class Solution:
    def validStrings(self, n: int) -> list[str]:
        res = []
        def bt(s, last):
            if len(s) == n:
                res.append(s)
                return
            bt(s + '1', '1')
            if last != '0':
                bt(s + '0', '0')
        bt('', '1')
        return res

