class Solution {
public:
    vector<string> validStrings(int n) {
        vector<string> res;
        string cur;
        function<void(char)> bt = [&](char last) {
            if ((int)cur.size() == n) { res.push_back(cur); return; }
            cur.push_back('1'); bt('1'); cur.pop_back();
            if (last != '0') { cur.push_back('0'); bt('0'); cur.pop_back(); }
        };
        bt('1');
        return res;
    }
};

