class Solution {
    public List<String> validStrings(int n) {
        List<String> res = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        bt(sb, '1', n, res);
        return res;
    }
    private void bt(StringBuilder sb, char last, int n, List<String> res) {
        if (sb.length() == n) { res.add(sb.toString()); return; }
        sb.append('1'); bt(sb, '1', n, res); sb.deleteCharAt(sb.length() - 1);
        if (last != '0') { sb.append('0'); bt(sb, '0', n, res); sb.deleteCharAt(sb.length() - 1); }
    }
}

