class Solution {
public:
    vector<string> validStrings(int n) {
        vector<string> res;
        for (int m = 0; m < (1 << n); m++) {
            string s(n, '0');
            for (int i = 0; i < n; i++) if (m >> i & 1) s[n - 1 - i] = '1';
            if (s.find("00") == string::npos) res.push_back(s);
        }
        return res;
    }
};

