class Solution {
    public List<String> validStrings(int n) {
        List<String> res = new ArrayList<>();
        for (int m = 0; m < (1 << n); m++) {
            StringBuilder sb = new StringBuilder();
            for (int i = n - 1; i >= 0; i--) sb.append((m >> i & 1) == 1 ? '1' : '0');
            String s = sb.toString();
            if (!s.contains("00")) res.add(s);
        }
        return res;
    }
}

